css:
.framesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2520;
    background:
        repeating-linear-gradient(0deg, rgba(120, 90, 60, 0.025) 0px, rgba(120, 90, 60, 0.025) 1px, transparent 1px, transparent 4px),
        linear-gradient(180deg, #f6efe2 0%, #f1e8d6 100%);
    border: 1px solid #d9caaa;
    border-radius: 6px;
}

.framesim-container * {
    box-sizing: border-box;
}

.framesim-masthead {
    text-align: center;
    padding: 20px 18px 22px;
    background: #fbf7ee;
    border: 2px solid #2a2520;
    border-radius: 4px;
    margin-bottom: 20px;
    box-shadow: 0 6px 0 rgba(42, 37, 32, 0.08);
}

.framesim-masthead-rule {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    border-bottom: 1px solid #b7a98a;
    padding-bottom: 8px;
    margin-bottom: 12px;
}

.framesim-dateline {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6b5d45;
}

.framesim-edition {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 2px;
    font-weight: 800;
    color: #8a2f25;
}

.framesim-masthead h1 {
    margin: 4px 0 12px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.7rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #1f1b16;
    line-height: 1.05;
}

.framesim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 0.98rem;
    line-height: 1.6;
    color: #4a4339;
    font-family: Georgia, 'Times New Roman', serif;
}

.framesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 700;
    color: #6b5d45;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.framesim-period-counter #currentDay,
.framesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #8a2f25;
}

.framesim-round-name {
    background: #2a2520;
    color: #f6efe2;
    padding: 3px 12px;
    border-radius: 3px;
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-left: 4px;
}

.framesim-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 800;
    color: #8a2f25;
    background: rgba(138, 47, 37, 0.10);
    border: 1px solid rgba(138, 47, 37, 0.35);
    padding: 4px 12px;
    border-radius: 3px;
}

.framesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.framesim-status-card {
    background: #fbf7ee;
    border-radius: 4px;
    padding: 16px 16px 14px;
    border: 1px solid #d9caaa;
    border-top: 4px solid #4a6275;
    box-shadow: 0 3px 0 rgba(42, 37, 32, 0.06);
}

.framesim-card-buyin { border-top-color: #3f7d52; }
.framesim-card-clarity { border-top-color: #4a6275; }
.framesim-card-resist { border-top-color: #8a2f25; }
.framesim-card-speed { border-top-color: #b07a1e; }

.framesim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 800;
    color: #6b5d45;
}

.framesim-value {
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.05;
    margin: 4px 0 2px;
    color: #1f1b16;
    font-variant-numeric: tabular-nums;
}

.framesim-card-buyin .framesim-value { color: #3f7d52; }
.framesim-card-clarity .framesim-value { color: #4a6275; }
.framesim-card-resist .framesim-value { color: #8a2f25; }
.framesim-card-speed .framesim-value { color: #b07a1e; }

.framesim-sublabel {
    font-size: 0.74rem;
    color: #7a6e58;
    line-height: 1.35;
}

.framesim-card-buyin.framesim-good .framesim-value { color: #2f6b42; }
.framesim-card-buyin.framesim-bad .framesim-value { color: #8a2f25; }
.framesim-card-resist.framesim-high { border-top-color: #a3261a; }
.framesim-card-resist.framesim-high .framesim-value { color: #a3261a; }
.framesim-card-resist.framesim-low { border-top-color: #3f7d52; }
.framesim-card-resist.framesim-low .framesim-value { color: #3f7d52; }
.framesim-card-speed.framesim-slip { border-top-color: #a3261a; }
.framesim-card-speed.framesim-slip .framesim-value { color: #a3261a; }

.framesim-trust-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2a2520;
    color: #f1e8d6;
    padding: 10px 18px;
    border-radius: 4px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

.framesim-trust-bar #trustDisplay {
    font-size: 1rem;
    letter-spacing: 0.3px;
    color: #e9c46a;
    text-transform: none;
}

.framesim-briefing {
    display: flex;
    gap: 14px;
    background: #fbf7ee;
    border-left: 5px solid #8a2f25;
    border-top: 1px solid #d9caaa;
    border-right: 1px solid #d9caaa;
    border-bottom: 1px solid #d9caaa;
    border-radius: 4px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 3px 0 rgba(42, 37, 32, 0.05);
}

.framesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.framesim-briefing-title {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 800;
    font-size: 1.12rem;
    color: #1f1b16;
    margin-bottom: 6px;
}

.framesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #43392c;
    font-family: Georgia, 'Times New Roman', serif;
}

.framesim-briefing-text strong { color: #8a2f25; }
.framesim-briefing-text em { color: #4a6275; font-style: italic; }

.framesim-controls {
    background: #fbf7ee;
    border-radius: 4px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9caaa;
    box-shadow: 0 3px 0 rgba(42, 37, 32, 0.05);
}

.framesim-controls h3 {
    margin: 0 0 16px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.18rem;
    font-weight: 800;
    color: #1f1b16;
    border-bottom: 2px solid #2a2520;
    padding-bottom: 8px;
}

.framesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3328;
    margin: 16px 0 6px;
}

.framesim-container select,
.framesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b7a98a;
    border-radius: 4px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #2a2520;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.framesim-container select:focus,
.framesim-container input[type="number"]:focus {
    outline: none;
    border-color: #8a2f25;
    box-shadow: 0 0 0 3px rgba(138, 47, 37, 0.15);
}

.framesim-container select option {
    background-color: #fffdf8;
    color: #2a2520;
}

.framesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #8a2f25;
}

.framesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b5d45;
    margin-top: 4px;
}

.framesim-range-readout span:last-child {
    color: #8a2f25;
    font-weight: 800;
}

.framesim-hint {
    font-size: 0.8rem;
    color: #7a6e58;
    margin-top: 4px;
    line-height: 1.45;
    font-style: italic;
}

.framesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.framesim-container .btn-primary {
    background: #8a2f25;
    border: none;
    color: #fbf7ee;
    padding: 11px 28px;
    border-radius: 4px;
    letter-spacing: 0.4px;
    box-shadow: 0 4px 0 #5e1f18;
}

.framesim-container .btn-primary:hover {
    background: #9c382c;
}

.framesim-container .btn-primary:active {
    transform: translateY(2px);
    box-shadow: 0 2px 0 #5e1f18;
}

.framesim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #b7a98a;
    color: #6b5d45;
    background: transparent;
    border-radius: 4px;
}

.framesim-coach {
    background: #2a2520;
    color: #ece3cf;
    border-radius: 4px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border-left: 5px solid #e9c46a;
    box-shadow: 0 3px 0 rgba(42, 37, 32, 0.10);
}

.framesim-coach-header {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 800;
    color: #e9c46a;
    margin-bottom: 8px;
}

.framesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
    font-family: Georgia, 'Times New Roman', serif;
}

.framesim-coach-body strong { color: #e9c46a; }
.framesim-coach-body em { color: #d7a8a1; font-style: italic; }

.framesim-history,
.framesim-chart {
    background: #fbf7ee;
    border-radius: 4px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9caaa;
    box-shadow: 0 3px 0 rgba(42, 37, 32, 0.05);
}

.framesim-history h3,
.framesim-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f1b16;
}

.framesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a3328;
}

.framesim-container table#usfHistoryTable th {
    background: #2a2520;
    color: #e9c46a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.5px;
    padding: 8px 10px;
    border-bottom: 2px solid #2a2520;
}

.framesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e2d6bb;
    color: #43392c;
}

.framesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f3ecdb;
}

.framesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .framesim-container {
        padding: 14px;
    }
    .framesim-masthead h1 {
        font-size: 1.9rem;
    }
    .framesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .framesim-value {
        font-size: 2.1rem;
    }
    .framesim-clock {
        margin-left: 0;
    }
    .framesim-period-counter {
        font-size: 0.86rem;
    }
    .framesim-trust-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .framesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .frm-cm-*, change violet/amber) ── */
.frm-cm { margin-top: 8px; }
.frm-cm-incomplete { text-align: center; color: #5c5470; font-size: 1rem; padding: 18px; }
.frm-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.frm-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #432470 0%, #7b4bc9 55%, #e0a02e 140%); color: #fff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(67,36,112,0.28); }
.frm-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.frm-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.frm-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f0dcae; }
.frm-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fff; border: 1px solid #e3dcec; border-left: 5px solid #7b4bc9; border-radius: 14px; padding: 16px 20px; }
.frm-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #675e77; }
.frm-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #432470; line-height: 1.15; }
.frm-cm-section { margin-bottom: 16px; }
.frm-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #675e77; margin-bottom: 8px; }
.frm-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.frm-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.frm-cm-ok { background: #ecf4ec; color: #2f6d3a; border-color: #b6ddb8; }
.frm-cm-no { background: #f7ecf6; color: #8a2a86; border-color: #e2c2e0; }
.frm-cm-ico { font-weight: 800; }
.frm-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.frm-cm-kpi { background: #f6f3fa; border: 1px solid #e5ddf0; border-radius: 12px; padding: 12px 14px; text-align: center; }
.frm-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #432470; }
.frm-cm-kpi-lbl { margin-top: 2px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700; color: #675e77; }
.frm-cm-kpi-sub { margin-top: 2px; font-size: 0.68rem; color: #8f869c; }
.frm-cm-insights { margin: 0; padding-left: 18px; }
.frm-cm-insights li { font-size: 0.9rem; color: #3b3543; margin-bottom: 6px; line-height: 1.45; }

