(function() {
    'use strict';

    class FramingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Framing the Change`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Calderwood Building Society, Project Horizon).
            this.TRUST_BASELINE = 34;     // % staff who believe leadership is honest about change
            this.BUYIN_TARGET = 60;       // credibility target to close the gap
            this.ROLES_AFFECTED = 480;    // of 1,850 front-line roles
            this.SAVINGS_AT_RISK = 6;     // GBP 6m slipped to next year if the window is missed

            // Concept truths (the identity-fit, honest, dialogic, reframing path).
            this.TRUE_DOMINANT = `family`;     // Calderwood's identity is the people-first mutual story
            this.TRUE_METAPHOR = `renewal`;    // honest about loss AND future-oriented for a mutual
            this.TRUE_TUNING = `tuned`;        // one metaphor, audience-tuned words
            this.TRUE_DISSENT = `engage`;      // dialogic co-authorship
            this.TRUE_RESPONSE = `reframe`;    // absorb, don't suppress
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    buyin: this.TRUST_BASELINE,   // front-line acceptance (starts at 34% trust baseline)
                    clarity: 25,                  // how clearly the framing lands
                    resist: 45,                   // grievances / press / counter-stories (lower better)
                    speed: 100,                   // % of the 31 March deadline protected
                    routedAround: false,          // R3 dissent decision ceded authorship
                    euphemism: false,             // warm metaphor that hid the 480-role loss
                    machineFrame: false,          // efficiency framing on a people-first identity
                    suppressed: false,            // tried to ban the Round 4 counter-narrative
                    buyinHistory: [this.TRUST_BASELINE],
                    clarityHistory: [25],
                    resistHistory: [45],
                    speedHistory: [100],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    dominant: `family`,
                    gap: `comms`,
                    rigour: 50,
                    metaphor: `journey`,
                    honesty: 50,
                    reject: `none`,
                    tuning: `twotuned`,
                    emphasis: `vision`,
                    dissent: `contain`,
                    consult: 20,
                    response: `hold`,
                    voice: `statement`,
                    deadline: `protect`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dm = document.getElementById(`dominantInput`);
                const gp = document.getElementById(`gapInput`);
                const rg = document.getElementById(`rigourInput`);
                if (dm) decisions.dominant = dm.value;
                if (gp) decisions.gap = gp.value;
                if (rg) decisions.rigour = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const mt = document.getElementById(`metaphorInput`);
                const hn = document.getElementById(`honestyInput`);
                const rj = document.getElementById(`rejectInput`);
                if (mt) decisions.metaphor = mt.value;
                if (hn) decisions.honesty = parseInt(hn.value, 10);
                if (rj) decisions.reject = rj.value;
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 3) {
                const tn = document.getElementById(`tuningInput`);
                const em = document.getElementById(`emphasisInput`);
                const di = document.getElementById(`dissentInput`);
                const cs = document.getElementById(`consultInput`);
                if (tn) decisions.tuning = tn.value;
                if (em) decisions.emphasis = em.value;
                if (di) decisions.dissent = di.value;
                if (cs) decisions.consult = parseInt(cs.value, 10);
                if (!Number.isFinite(decisions.consult) || decisions.consult < 0 || decisions.consult > 100) {
                    warn(`warn_consult_range`); return false;
                }
            } else if (round === 4) {
                const rs = document.getElementById(`responseInput`);
                const vc = document.getElementById(`voiceInput`);
                const dl = document.getElementById(`deadlineInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rs) decisions.response = rs.value;
                if (vc) decisions.voice = vc.value;
                if (dl) decisions.deadline = dl.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 — verbatim v1.0.0 composite, extracted so calculateResults and getPerformanceSummary agree.
            const buyin = Math.round(ds.buyin);
            const clarity = Math.round(ds.clarity);
            const resist = Math.round(ds.resist);
            const speed = Math.round(ds.speed);
            return Math.round(
                buyin * 0.34 + clarity * 0.24 + (100 - resist) * 0.26 + speed * 0.16
            );
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let buyinDelta = 0, clarityDelta = 0, resistDelta = 0, speedDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the discourse landscape (read the identity, the trust gap).
                switch (d.dominant) {
                    case `family`: clarityDelta += 8; buyinDelta += 4; resistDelta -= 4; coachKey = `coach_r1_family`; break;
                    case `fortress`: clarityDelta += 2; coachKey = `coach_r1_fortress`; break;
                    case `machine`: clarityDelta -= 2; resistDelta += 3; coachKey = `coach_r1_machine`; break;
                    case `none`: clarityDelta -= 6; resistDelta += 6; coachKey = `coach_r1_none`; break;
                }

                // Read the 34% trust baseline correctly: it is a CREDIBILITY gap.
                switch (d.gap) {
                    case `credibility`: buyinDelta += 8; clarityDelta += 4; resistDelta -= 4; if (d.dominant === `family`) coachKey = `coach_r1_sharp`; break;
                    case `comms`: buyinDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r1_comms` : coachKey; break;
                    case `morale`: buyinDelta -= 3; resistDelta += 4; break;
                    case `ignore`: buyinDelta -= 6; resistDelta += 7; coachKey = `coach_r1_ignore`; break;
                }

                if (d.rigour >= 60) { clarityDelta += 6; resistDelta -= 4; }
                else if (d.rigour <= 25) { clarityDelta -= 5; resistDelta += 4; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.dominant === `family` && d.gap === `credibility`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the governing metaphor (Common Errors 1 & 2).
                const h = d.honesty / 100;
                switch (d.metaphor) {
                    case `renewal`:
                        // Honest about loss AND future-oriented — best fit for a people-first mutual.
                        clarityDelta += 10; buyinDelta += 8; resistDelta -= 6; coachKey = `coach_r2_renewal`;
                        break;
                    case `journey`:
                        // Enables progress narrative; constrains honesty about losses unless you push it.
                        clarityDelta += 8; buyinDelta += 4; resistDelta -= 2; coachKey = `coach_r2_journey`;
                        break;
                    case `organism`:
                        // "Evolving to survive" — plausible, but naturalises the cuts and downplays agency.
                        clarityDelta += 4; buyinDelta += 1; coachKey = `coach_r2_organism`;
                        break;
                    case `machine`:
                        // Common Error 1: efficiency framing tells 1,850 people they are cogs.
                        clarityDelta += 6; buyinDelta -= 12; resistDelta += 12; ds.machineFrame = true; coachKey = `coach_r2_machine`;
                        break;
                }

                // Honesty about the 480 lost roles. Euphemism opens a credibility gap (Common Error 2).
                if (d.honesty >= 60) {
                    buyinDelta += (h - 0.5) * 18; resistDelta -= (h - 0.5) * 14; clarityDelta += 2;
                } else if (d.honesty <= 30) {
                    // A warm/soft frame that hides the loss reads as spin once reality contradicts it.
                    const softFrame = (d.metaphor === `journey` || d.metaphor === `organism`);
                    buyinDelta -= softFrame ? 12 : 7;
                    resistDelta += softFrame ? 10 : 6;
                    ds.euphemism = true;
                    coachKey = `coach_r2_euphemism`;
                }

                // Naming what you reject is the conscious-choice discipline Oswick asks for.
                switch (d.reject) {
                    case `machine`: clarityDelta += 5; buyinDelta += 3; resistDelta -= 3; break;
                    case `family`: clarityDelta += 2; break;
                    case `none`: clarityDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_rejectnone` : coachKey; break;
                }

                summaryKey = (d.metaphor === `machine`) ? `sum_r2_machine` :
                             (ds.euphemism ? `sum_r2_euphemism` :
                             ((d.metaphor === `renewal` || d.metaphor === `journey`) && d.honesty >= 60 ? `sum_r2_good` : `sum_r2_weak`));
            } else if (round === 3) {
                // Craft three messages + the dissent decision (Common Errors 3 & 4).
                switch (d.tuning) {
                    case `tuned`: clarityDelta += 12; buyinDelta += 6; resistDelta -= 6; coachKey = `coach_r3_tuned`; break;
                    case `twotuned`: clarityDelta += 4; resistDelta += 2; break;
                    case `generic`: clarityDelta -= 8; buyinDelta -= 6; resistDelta += 8; coachKey = `coach_r3_generic`; break;
                }

                // The member message in "only branch in town" closures (28 of 28).
                switch (d.emphasis) {
                    case `commitment`: buyinDelta += 6; resistDelta -= 6; clarityDelta += 3; break;
                    case `vision`: resistDelta += 3; break;
                    case `reassure`: buyinDelta -= 4; resistDelta += 5; coachKey = (coachKey === `coach_default`) ? `coach_r3_reassure` : coachKey; break;
                }

                // The dissent decision: dialogic vs monologic, under the three-week clock.
                switch (d.dissent) {
                    case `engage`:
                        // Co-authorship: costs time now, buys durable buy-in and pre-empts the counter-narrative.
                        buyinDelta += 10; resistDelta -= 10; speedDelta -= 6; coachKey = `coach_r3_engage`;
                        break;
                    case `contain`:
                        buyinDelta -= 2; resistDelta += 3; coachKey = (coachKey === `coach_default` || coachKey === `coach_r3_reassure`) ? `coach_r3_contain` : coachKey;
                        break;
                    case `route`:
                        // Common Error 3: cede authorship — the union writes the counter-narrative for you.
                        buyinDelta -= 8; resistDelta += 10; speedDelta += 4; ds.routedAround = true; coachKey = `coach_r3_route`;
                        break;
                }

                // Consultation time trades rollout speed for buy-in (the real change-leader tension).
                if (d.consult >= 50) { buyinDelta += 4; resistDelta -= 3; speedDelta -= 8; }
                else if (d.consult <= 10) { buyinDelta -= 3; resistDelta += 3; speedDelta += 3; }

                summaryKey = (d.tuning === `tuned` && d.dissent === `engage`) ? `sum_r3_good` :
                             (ds.routedAround ? `sum_r3_route` :
                             (d.tuning === `generic` ? `sum_r3_generic` : `sum_r3_weak`));
            } else if (round === 4) {
                // Launch day: absorb the counter-narrative (Common Error 5: suppression).
                // Routing around dissent in R3 makes the counter-narrative bite harder.
                const routedPenalty = ds.routedAround ? 1.5 : 1.0;

                switch (d.response) {
                    case `reframe`:
                        buyinDelta += 12; clarityDelta += 8; resistDelta -= 12; coachKey = `coach_r4_reframe`;
                        break;
                    case `hold`:
                        buyinDelta -= 4 * routedPenalty; resistDelta += 6 * routedPenalty; coachKey = `coach_r4_hold`;
                        break;
                    case `suppress`:
                        // "Cease and correct" validates the counter-story by fighting it head-on.
                        buyinDelta -= 12 * routedPenalty; clarityDelta -= 4; resistDelta += 14 * routedPenalty;
                        ds.suppressed = true; coachKey = `coach_r4_suppress`;
                        break;
                }

                // Who speaks, and how — dialogue closes the sensegiving/sensemaking gap.
                switch (d.voice) {
                    case `dialogue`: buyinDelta += 8; resistDelta -= 6; clarityDelta += 3; if (d.response === `reframe`) coachKey = `coach_r4_dialogue`; break;
                    case `statement`: resistDelta += 2; break;
                    case `silence`: buyinDelta -= 6; resistDelta += 8; coachKey = (coachKey === `coach_r4_hold`) ? `coach_r4_silence` : coachKey; break;
                }

                // Protect the deadline vs buy time — phasing is the balanced move.
                switch (d.deadline) {
                    case `phase`: speedDelta += 0; buyinDelta += 4; resistDelta -= 4; clarityDelta += 2; break;
                    case `protect`: speedDelta += 2; resistDelta += 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_protect` : coachKey; break;
                    case `delay`: speedDelta -= 22; buyinDelta += 3; resistDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_delay` : coachKey; break;
                }

                if (d.conviction >= 60) { buyinDelta += 4; resistDelta -= 3; }
                else if (d.conviction <= 25) { buyinDelta -= 4; resistDelta += 4; }

                summaryKey = (d.response === `reframe` && d.voice === `dialogue`) ? `sum_r4_good` :
                             (ds.suppressed ? `sum_r4_suppress` : `sum_r4_weak`);
            }

            // Apply deltas. Buy-in, clarity, resistance on 0–100; speed is the % of deadline protected.
            ds.buyin = Math.max(0, Math.min(100, Math.round(ds.buyin + buyinDelta)));
            ds.clarity = Math.max(0, Math.min(100, Math.round(ds.clarity + clarityDelta)));
            ds.resist = Math.max(0, Math.min(100, Math.round(ds.resist + resistDelta)));
            ds.speed = Math.max(0, Math.min(100, Math.round(ds.speed + speedDelta)));

            ds.buyinHistory.push(ds.buyin);
            ds.clarityHistory.push(ds.clarity);
            ds.resistHistory.push(ds.resist);
            ds.speedHistory.push(ds.speed);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                buyin: ds.buyin,
                buyinDelta: Math.round(buyinDelta),
                clarity: ds.clarity,
                clarityDelta: Math.round(clarityDelta),
                resist: ds.resist,
                resistDelta: Math.round(resistDelta),
                speed: ds.speed,
                speedDelta: Math.round(speedDelta),
                routedAround: ds.routedAround,
                euphemism: ds.euphemism,
                machineFrame: ds.machineFrame,
                suppressed: ds.suppressed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

