        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const buyin = Math.round(ds.buyin);
            const clarity = Math.round(ds.clarity);
            const resist = Math.round(ds.resist);
            const speed = Math.round(ds.speed);

            // v1.1.0 — reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const accepted = buyin >= this.BUYIN_TARGET;
            const clear = clarity >= 60;
            const calm = resist <= 35;
            const onTime = speed >= 85;
            const blewUp = ds.machineFrame || ds.suppressed || ds.euphemism || resist >= 70;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_backfired`;
            if (accepted && clear && calm && onTime && composite >= 75) tierKey = `grade_landed`;
            else if (accepted && calm) tierKey = `grade_buyin`;
            else if (blewUp) tierKey = `grade_counter`;
            else if (!onTime && speed <= 70) tierKey = `grade_deadline`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (accepted && clear && calm && onTime) insights.push(window.mySimulation.t(`insight_landed`));
            else if (blewUp) insights.push(window.mySimulation.t(`insight_backfired`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.machineFrame) insights.push(window.mySimulation.t(`insight_machine`));
            if (ds.euphemism) insights.push(window.mySimulation.t(`insight_euphemism`));
            if (ds.routedAround) insights.push(window.mySimulation.t(`insight_routed`));
            if (ds.suppressed) insights.push(window.mySimulation.t(`insight_suppressed`));
            if (!onTime) insights.push(window.mySimulation.t(`insight_slow`));
            else if (accepted && calm) insights.push(window.mySimulation.t(`insight_dialogic`));

            return {
                buyin: buyin,
                clarity: clarity,
                resist: resist,
                speed: speed,
                accepted: accepted,
                clear: clear,
                calm: calm,
                onTime: onTime,
                blewUp: blewUp,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

