            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="frm-cm"><p class="frm-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="frm-cm-chip ` + (ok ? `frm-cm-ok` : `frm-cm-no`) + `">` +
